const input = $input.first().json;
const contractVersion = '1.0';
const testMode = input.testMode !== false;
const correlationId = typeof input.correlationId === 'string' && /^[A-Za-z0-9._:-]{1,128}$/.test(input.correlationId) ? input.correlationId : crypto.randomUUID();
const fail = (code,message) => [{json:{ok:false,contractVersion,testMode,correlationId,logged:false,error:{code,message}}}];
const allowed = new Set(['contractVersion','testMode','correlationId','eventType','outcome','subjectRef','occurredAt','metadata']);
if (Object.keys(input).some((key) => !allowed.has(key))) return fail('INVALID_REQUEST','Input contains unknown fields');
if (input.contractVersion !== undefined && input.contractVersion !== contractVersion) return fail('UNSUPPORTED_CONTRACT','contractVersion must be 1.0');
if (typeof input.eventType !== 'string' || !/^[a-z][a-z0-9._-]{2,63}$/.test(input.eventType)) return fail('INVALID_EVENT_TYPE','eventType must be a stable taxonomy key');
if (!['success','failure','denied','skipped'].includes(input.outcome)) return fail('INVALID_OUTCOME','outcome is not supported');
if (input.subjectRef !== undefined && (typeof input.subjectRef !== 'string' || !/^[A-Za-z0-9._:-]{3,128}$/.test(input.subjectRef))) return fail('PII_NOT_ALLOWED','subjectRef must be an opaque non-PII reference');
const occurredAt = new Date(input.occurredAt ?? Date.now());
if (Number.isNaN(occurredAt.getTime())) return fail('INVALID_TIME','occurredAt must be an ISO timestamp');
const metadata = input.metadata ?? {};
const metadataAllowed = new Set(['workflowKey','actionType','channel','durationMs','retryCount','errorCode']);
if (!metadata || Array.isArray(metadata) || typeof metadata !== 'object' || Object.keys(metadata).some((key) => !metadataAllowed.has(key))) return fail('PII_NOT_ALLOWED','metadata key is not on the minimal allowlist');
if (Object.values(metadata).some((value) => !['string','number','boolean'].includes(typeof value) || (typeof value === 'string' && value.length > 128) || (typeof value === 'number' && !Number.isFinite(value)))) return fail('INVALID_METADATA','metadata values must be short primitives');
const record = {eventType:input.eventType,outcome:input.outcome,correlationId,occurredAt:occurredAt.toISOString(),subjectRef:input.subjectRef ?? null,metadata};
if (!testMode) console.log(JSON.stringify({businessEvent:record}));
return [{json:{ok:true,contractVersion,testMode,correlationId,logged:!testMode,disposition:testMode?'preview':'emit',record}}];
